        for (int s = 0; s < TC_MAXI; s++) if (s < nimg) { const float v = warp_sum(psum[s]); if (lane == 0) inv_s[warp * 4 + s] = v; }
        nbar(bid, bn);
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++) {
          float tot = 0.f;
