// =====================================================================================================
// tcgen05 swap-AB cooperative path for the wide-C rows (512 threads, 16 warps)
// Phase A (unchanged from r11): plane loads (+ LN vectors, dwb/b2 slices) by bulk copy at entry, W1 loads in flight
//   during the depthwise conv, LN partials, fp16 d, out = x + b2, then the W1 conversion; the GRN sum buffers are
//   zeroed here (gsum[B] for whole-image ranges, gsq[B][4C] otherwise). Sync 1 (flat barrier).
// Phase B (r13, H53 on top of r12 H49): GEMM1 tiles = (128 hidden rows, padded token range [t0, t0+R)), R a multiple
//   of 8 per row (static table; a range may straddle images), tile t = hidden block t % HT of range t / HT. Epilogue on
//   all 16 warps (warps 4-15 on every tile, warps 0-3 join the CTA's last tile). Pass 1: LN fold + A&S erfc GELU in
//   fp32, per-(image,k) sumsq split at the static image boundaries (each 8-column group lies in one image), fp32 h back
//   into the tile's TMEM columns. Whole-image ranges (R % HWS == 0, the r12 path): gf = sqrt(sumsq) is local and
//   sum_k gf is red.add-ed into gsum[b]. Straddling ranges: the (image,k) partials are red.add-ed into gsq[b][k]. One
//   thread then publishes (red.release.gpu) on one counter cell per range (whole) or per touched image (straddling),
//   polls every cell in one ld.acquire loop until each has its static target (HT x ranges touching the image), and
//   counts its departures; the last departer resets the cell. inv_b = 1 / (mean_k gf + eps) comes from gsum[b] (whole)
//   or from a CTA reduction of sqrt(gsq[b][:]) (straddling; one round of predicated float4 loads), and pass 2 stores
//   h' = fp16(h * (1 + gw*gf*inv_b)) once. A tile publishes before it waits and tiles sharing an image are < P tile
//   indices apart (host check), so with co-resident CTAs the waits have no cycle. Sync 2.
// Phase C: GEMM2 split-K over h' (single accumulator, MP channel tiles per unit, two TMEM buffers), drain 7x7 by
//   whole-image bulk reduce, 14x14 by float4 red.add into the x + b2 prefill (+ W2.gb on the first k-split).
// TC_STAMPS: globaltimer diagnostics (off in the shipped build).
// =====================================================================================================
#ifndef TC_STAMPS
#define TC_STAMPS 0
#endif
#define TC_NT 512
#define TC_RING (192 * 1024)
#define TC_STGB 2560
#define TC_OFF_STG TC_RING
#define TC_OFF_MS (TC_OFF_STG + 8 * TC_STGB)
#define TC_OFF_SQ (TC_OFF_MS + 4096)
#define TC_OFF_INV (TC_OFF_SQ + 4096)
#define TC_OFF_CB (TC_OFF_INV + 512)
#define TC_OFF_BAR (TC_OFF_CB + 512)
#define TC_NBARS 34
#define TC_SMEM (TC_OFF_BAR + (TC_NBARS + 1) * 8 + 1024)
#define TC_NS2MAX 8
#define TC_MAXI 4
// phase-C bulk-reduce staging tile [128 ch][49] fp32 (7x7 units that are not the CTA's last): after the ring, over
// buffers used only in phase B; the last unit stages its tiles in the (then free) ring
#define TC_OFF_RS TC_RING
static_assert(TC_OFF_RS + 128 * 49 * 4 <= TC_OFF_INV, "bulk staging overlaps inv/cb");
// phase-B buffers of the all-warp epilogue inside the ring (multi-tile GEMM1 rings use <= 160 KB): per-warp staging,
// per-(warp group, row) sumsq parts for <= TC_MAXI images
#define TC_B_STG (160 * 1024)
#define TC_B_STGW 1536
#define TC_B_SQ (TC_B_STG + 16 * TC_B_STGW)
// phase-A small-vector area inside the ring: LN weight/bias (2*C floats), per-unit dwb and b2 slices
#define TC_PA_LN (116 * 1024)
