    L=ctypes.CDLL(f'{D}/{tag}.so'); L.ws_launch.argtypes=[ctypes.POINTER(WSArgs),ctypes.c_void_p]; L.ws_launch.restype=ctypes.c_char_p
    L.ws_workspace_bytes.argtypes=[ctypes.c_int]*4; L.ws_workspace_bytes.restype=ctypes.c_longlong; return L
