    h=F.gelu(a@w1.double().T+b1.double())
    gx=torch.norm(h,p=2,dim=(1,2),keepdim=True); nx=gx/(gx.mean(dim=-1,keepdim=True)+1e-6)
    h=gw.double()*(h*nx)+gb.double()+h
    return xd+(h@w2.double().T+b2.double()).permute(0,3,1,2)
