torch.manual_seed(200)
for (B,C,H,W,atol) in [(16,384,14,14,3.3e-3),(32,768,7,7,2.9e-3),(8,384,14,14,2.8e-3)]:
    mx=0.; nb=0
    for rd in range(10):
        ins=gen(B,C,H,W); out=torch.full((B,C,H,W),float('nan'),device='cuda'); run(L,ins,out); r=ref(*ins)
        err=(out.double()-r).abs(); mx=max(mx,err.max().item()); nb+=int((err>atol+1e-5*r.abs()).sum().item())
    ins=gen(B,C,H,W); r=ref(*ins); out=torch.empty(B,C,H,W,device='cuda'); worst=0.; nans=0
    for i in range(400):
        out.fill_(float('nan')); run(L,ins,out)
        if i%8==7: worst=max(worst,(out.double()-r).abs().max().item()); nans+=int(torch.isnan(out).sum().item())
    res={'r12':[], 'fin':[]}
    for rd in range(3):
        res['r12'].append(harness_time(mk(Lr),ins,[out])); res['fin'].append(harness_time(mk(L),ins,[out]))
    print((B,C), f'10-round max {mx:.3e} ({100*mx/atol:.0f}% atol) beyond {nb} | stress400 worst {worst:.3e} nan {nans} | r12 {statistics.median(res["r12"]):.2f} fin {statistics.median(res["fin"]):.2f}')

