      if (j == 0) {
        if (whole) {
          const float g4[4] = {sqrtf(sl.x), sqrtf(sl.y), sqrtf(sl.z), sqrtf(sl.w)};
#pragma unroll
          for (int s = 0; s < TC_MAXI; s++) if (s < nimg) { const float w_ = warp_sum(g4[s]); if (lane == 0) atomicAdd(p.gsum + img0 + s, w_); }
        } else {
          float* gk = p.gsq + (size_t)img0 * C4 + k;
          atomicAdd(gk, sl.x);
          if (nimg > 1) atomicAdd(gk + C4, sl.y);
          if (nimg > 2) atomicAdd(gk + 2 * C4, sl.z);
          if (nimg > 3) atomicAdd(gk + 3 * C4, sl.w);
        }
      }
      nbar(bid, bn);
      if (warp == 4 && lane == 0) {
        const int nc = whole ? 1 : nimg;
        unsigned int tg[TC_MAXI];
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++) {
          const int b = img0 + s;
          tg[s] = whole ? (unsigned int)HT : (unsigned int)(HT * (((b + 1) * HWS - 1) / R - (b * HWS) / R + 1));
        }
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++)
          if (s < nc) asm volatile("red.release.gpu.global.add.u32 [%0], 1;" ::"l"(g_img_cnt + (img0 + s) * 32) : "memory");
        bool done;
        do {
          done = true;
#pragma unroll
          for (int s = 0; s < TC_MAXI; s++)
            if (s < nc) {
              unsigned int cur;
              asm volatile("ld.acquire.gpu.global.u32 %0, [%1];" : "=r"(cur) : "l"(g_img_cnt + (img0 + s) * 32) : "memory");
