#pragma unroll
        for (int s = 0; s < TC_MAXI; s++) {
          old[s] = 0u;
          if (s < nc) asm volatile("atom.relaxed.gpu.global.add.u32 %0, [%1], 1;" : "=r"(old[s]) : "l"(g_img_dep + (img0 + s) * 32) : "memory");
