      }
      nbar(bid, bn);
      float sc[TC_MAXI];
      if (whole) {
        const float sl4[4] = {sl.x, sl.y, sl.z, sl.w};
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++)
