      } else {
        constexpr int NL4 = (C4 / 4 + 383) / 384;
        float gfo[TC_MAXI], psum[TC_MAXI];
        float4 gv[TC_MAXI][NL4];
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++) {
          const float* gs = p.gsq + (size_t)(img0 + s) * C4;
          gfo[s] = (s < nimg) ? __ldcg(gs + k) : 0.f;
#pragma unroll
          for (int i = 0; i < NL4; i++) {
