  tfb(); __syncthreads();
  if (warp == 2) asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, 512;" ::"r"(tbase));
}
template __global__ void tc_kernel<768, 49>(const __grid_constant__ TCP p);
template __global__ void tc_kernel<384, 196>(const __grid_constant__ TCP p);

#include <torch/extension.h>
