  constexpr int HWS = (HW_ + 7) / 8 * 8;
  extern __shared__ __align__(1024) unsigned char tc_raw[];
  unsigned char* sm = tc_raw + ((1024u - (sa(tc_raw) & 1023u)) & 1023u);
  unsigned char* ring = sm;
  float* inv_s = reinterpret_cast<float*>(sm + TC_OFF_INV);
  int* cb_s = reinterpret_cast<int*>(sm + TC_OFF_CB);
  uint64_t* bars = reinterpret_cast<uint64_t*>(sm + TC_OFF_BAR);
  uint64_t *full1 = bars, *empty1 = bars + 4, *tf1 = bars + 8, *te1 = bars + 10;
  uint64_t *full2 = bars + 12, *empty2 = bars + 20, *tf2 = bars + 28, *te2 = bars + 30, *cbar = bars + 32, *sbar = bars + 33;
  uint32_t* tslot = reinterpret_cast<uint32_t*>(bars + TC_NBARS);
  const int tid = threadIdx.x, warp = __shfl_sync(0xffffffffu, tid >> 5, 0), lane = tid & 31;
  const int cta = blockIdx.x, P = gridDim.x;
  if (tid == 0) {
    for (int i = 0; i < TC_NBARS; i++) mb_init(bars + i, (i == 30 || i == 31) ? 8u : 1u);
    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
  }
  if (warp == 2) {
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], 512;" ::"r"(sa(tslot)));
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;");
  }
  tfb(); __syncthreads(); tfa();
  const uint32_t tbase = *tslot;
  if (tid == 0) STAMP(0);

  // ---------------- phase A: plane loads, W1 loads in flight, depthwise conv, LN partials, fp16 d, out = x + b2, W1 conversion
  const int nu = (cta < p.units) ? (p.units - cta + P - 1) / P : 0;
  float* xs = reinterpret_cast<float*>(ring);
  float* wsm = xs + nu * 32 * HW_;
  float* dbuf = wsm + nu * 32 * 49;
  float* lnw_s = reinterpret_cast<float*>(ring + TC_PA_LN);
  float* lnb_s = lnw_s + C_;
  float* dwb_s = reinterpret_cast<float*>(ring + TC_PA_PAR);
  float* b2_s = dwb_s + 256;
  if (tid == 0) {
    mb_expect(sbar, 2 * C_ * 4);
    bulk_g2s(lnw_s, p.lnw, C_ * 4, sbar);
    bulk_g2s(lnb_s, p.lnb, C_ * 4, sbar);
    if (nu > 0) {
      mb_expect(cbar, nu * (32 * HW_ * 4 + 32 * 49 * 4 + 2 * 32 * 4));
      for (int i = 0; i < nu; i++) {
        const int u = cta + i * P, b = u / G, g = u - b * G;
        bulk_g2s(xs + i * 32 * HW_, p.x + ((size_t)b * C_ + g * 32) * HW_, 32 * HW_ * 4, cbar);
        bulk_g2s(wsm + i * 32 * 49, p.dww + (size_t)g * 32 * 49, 32 * 49 * 4, cbar);
        bulk_g2s(dwb_s + i * 32, p.dwb + g * 32, 128, cbar);
        bulk_g2s(b2_s + i * 32, p.b2 + g * 32, 128, cbar);
      }
    }
  }
  if (p.WHOLE) { if (cta == 0 && tid < p.B) p.gsum[tid] = 0.f; }
  else for (int i = cta * TC_NT + tid; i < p.B * C4; i += P * TC_NT) p.gsq[i] = 0.f;
  constexpr int NQ1 = C_ / 128, MW1 = (C_ >= 768) ? 2 : 1;
  const int nw1 = P * (TC_NT / 32), wb1 = (P - 1 - cta) * (TC_NT / 32) + warp;
  float4 w1v[MW1][NQ1];
#pragma unroll
  for (int k = 0; k < MW1; k++) {
    const int wu = wb1 + k * nw1;
    if (wu < C4) {
      const float4* src = reinterpret_cast<const float4*>(p.w1 + (size_t)wu * C_);
#pragma unroll
      for (int j = 0; j < NQ1; j++) w1v[k][j] = ldnc4(src + lane + 32 * j);
    }
  }
  if (nu > 0) {
    mb_wait(cbar, 0);
    constexpr int SEG = W_ / 7, per_plane = H_ * SEG;
    const int items = nu * 32 * per_plane;
    for (int itm = tid; itm < items; itm += TC_NT) {
      const int pl = itm / per_plane;
      const int rem = itm - pl * per_plane;
      const int h = rem / SEG, w0 = (rem - h * SEG) * 7;
      const int ui = pl >> 5, pp = pl & 31;
      const float* xp = xs + pl * HW_;
      const float* wp = wsm + pl * 49;
      float acc[7];
#pragma unroll
      for (int o = 0; o < 7; o++) acc[o] = 0.f;
#pragma unroll
      for (int i = 0; i < 7; i++) {
        const int hh = h + i - 3;
        if (hh >= 0 && hh < H_) {
          float v[13];
#pragma unroll
          for (int jj = 0; jj < 13; jj++) { const int col = w0 - 3 + jj; v[jj] = (col >= 0 && col < W_) ? xp[hh * W_ + col] : 0.f; }
          float wt[7];
#pragma unroll
          for (int jj = 0; jj < 7; jj++) wt[jj] = wp[i * 7 + jj];
#pragma unroll
          for (int o = 0; o < 7; o++)
#pragma unroll
            for (int jj = 0; jj < 7; jj++) acc[o] = fmaf(v[o + jj], wt[jj], acc[o]);
        }
      }
      const float bias = dwb_s[ui * 32 + pp];
      float* dp = dbuf + pl * HW_ + h * W_ + w0;
#pragma unroll
      for (int o = 0; o < 7; o++) dp[o] = acc[o] + bias;
    }
    __syncthreads();
    for (int e = tid; e < nu * HW_; e += TC_NT) {
      const int ui = e / HW_, hw = e - ui * HW_;
      const int u = cta + ui * P, b = u / G, g = u - b * G;
      float s1 = 0.f, s2 = 0.f;
#pragma unroll 8
      for (int pp = 0; pp < 32; pp++) { const float v = dbuf[(ui * 32 + pp) * HW_ + hw]; s1 += v; s2 = fmaf(v, v, s2); }
      reinterpret_cast<float2*>(p.part)[((size_t)b * G + g) * HW_ + hw] = make_float2(s1, s2);
    }
    constexpr int q8n = HWS / 8;
    for (int e = tid; e < nu * 32 * q8n; e += TC_NT) {
      const int pl = e / q8n, q8 = e - pl * q8n;
      const int ui = pl >> 5, pp = pl & 31;
      const int u = cta + ui * P, b = u / G, g = u - b * G;
      float v[8];
#pragma unroll
      for (int t = 0; t < 8; t++) { const int hw = q8 * 8 + t; v[t] = hw < HW_ ? dbuf[pl * HW_ + hw] : 0.f; }
      uint4 o;
      o.x = h2u(__floats2half2_rn(v[0], v[1])); o.y = h2u(__floats2half2_rn(v[2], v[3]));
      o.z = h2u(__floats2half2_rn(v[4], v[5])); o.w = h2u(__floats2half2_rn(v[6], v[7]));
      *reinterpret_cast<uint4*>(p.d16 + (size_t)(g * 32 + pp) * p.Mcols + b * HWS + q8 * 8) = o;
    }
    constexpr int n4u = 8 * HW_;
    for (int e = tid; e < nu * n4u; e += TC_NT) {
      const int ui = e / n4u, r = e - ui * n4u;
      const int u = cta + ui * P, b = u / G, g = u - b * G;
      float4 v = reinterpret_cast<const float4*>(xs)[e];
      const int i0 = r * 4;
      const float* b2g = b2_s + ui * 32;
      v.x += b2g[(i0 + 0) / HW_]; v.y += b2g[(i0 + 1) / HW_];
      v.z += b2g[(i0 + 2) / HW_]; v.w += b2g[(i0 + 3) / HW_];
      reinterpret_cast<float4*>(p.out + ((size_t)b * C_ + g * 32) * HW_)[r] = v;
    }
  }
  {
    // W1 conversion: fp16(W1*lnw), u = row sum of the fp16 values, v = W1.lnb + b1 (arithmetic and order unchanged)
    mb_wait(sbar, 0);
    const float4* lw4 = reinterpret_cast<const float4*>(lnw_s);
    const float4* lb4 = reinterpret_cast<const float4*>(lnb_s);
#pragma unroll
    for (int k = 0; k < MW1; k++) {
      const int wu = wb1 + k * nw1;
      if (wu < C4) {
        uint2* dst = reinterpret_cast<uint2*>(p.w1h + (size_t)wu * C_);
        float su = 0.f, sv = 0.f;
#pragma unroll
        for (int j = 0; j < NQ1; j++) {
          const int c4 = lane + 32 * j;
          const float4 lw = lw4[c4];
          const float4 lb = lb4[c4];
          const __half2 h0 = __floats2half2_rn(w1v[k][j].x * lw.x, w1v[k][j].y * lw.y);
          const __half2 h1 = __floats2half2_rn(w1v[k][j].z * lw.z, w1v[k][j].w * lw.w);
          const float2 f0 = __half22float2(h0), f1 = __half22float2(h1);
          su += (f0.x + f0.y) + (f1.x + f1.y);
          sv += w1v[k][j].x * lb.x + w1v[k][j].y * lb.y + w1v[k][j].z * lb.z + w1v[k][j].w * lb.w;
          uint2 o; o.x = h2u(h0); o.y = h2u(h1);
          dst[c4] = o;
        }
        su = warp_sum(su); sv = warp_sum(sv);
        if (lane == 0) { p.uk[wu] = su; p.vk[wu] = sv + __ldg(p.b1 + wu); }
      }
    }
  }
#if TC_STAMPS
  __syncthreads(); if (tid == 0) STAMP(1);
#endif
  asm volatile("fence.proxy.async.global;" ::: "memory");
  asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
  tfb(); gbar(P); tfa();
  if (tid == 0) STAMP(2);

  // ---------------- phase B: GEMM1 over (hidden block, token range) tiles, GRN scale behind the per-image counters
  const int Bz = min(P, p.T1), Ez = P - Bz, Wt = Ez * 16 + Bz * 12;
  if (cta >= p.T1) tc_w2_work<C_>(p, (cta - Bz) * 16 + warp, Wt, lane);
  const int R = p.R, N1 = p.N1;
  if (warp == 0) {
    asm volatile("fence.proxy.async.global;" ::: "memory");
    const uint32_t nst = (uint32_t)p.NST1;
    uint32_t it = 0;
    for (int t = cta; t < p.T1; t += P) {
      const int m0 = (t % HT) * 128, t0 = (t / HT) * R;
      for (int kb = 0; kb < KB1; kb++, it++) {
        const int s = (int)(it % nst); const uint32_t n = it / nst;
        if (it >= nst) mb_wait(empty1 + s, (n & 1) ^ 1);
        if (elect1()) {
          unsigned char* st = ring + s * p.STG1;
          mb_expect(full1 + s, 16384 + p.NAT1 * 8192);
          tma2d(st, &p.mW1, kb * 64, m0, full1 + s);
          for (int a = 0; a < p.NAT1; a++) tma2d(st + 16384 + a * 8192, &p.mD, t0 + a * 64, kb * 64, full1 + s);
        }
        __syncwarp();
      }
    }
  } else if (warp == 1) {
    // N1 > 256 (one tile per CTA only): two MMAs of 128 + (N1 - 128) columns into adjacent TMEM columns
    const uint32_t nst = (uint32_t)p.NST1;
    const int Na = N1 > 256 ? 128 : N1, Nb = N1 - Na;
    const uint32_t ida = (1u << 4) | (1u << 16) | ((uint32_t)(Na >> 3) << 17) | (8u << 24);
    const uint32_t idb = (1u << 4) | (1u << 16) | ((uint32_t)(Nb >> 3) << 17) | (8u << 24);
    uint32_t it = 0, ti = 0;
    for (int t = cta; t < p.T1; t += P, ti++) {
      const uint32_t buf = ti & 1;
      if (ti >= 2) { mb_wait(te1 + buf, ((ti >> 1) & 1) ^ 1); tfa(); }
      const uint32_t d = tbase + buf * 256;
      for (int kb = 0; kb < KB1; kb++, it++) {
        const int s = (int)(it % nst); const uint32_t n = it / nst;
        mb_wait(full1 + s, n & 1);
        tfa();
        if (elect1()) {
          const uint32_t a0 = sa(ring + s * p.STG1), b0 = a0 + 16384;
#pragma unroll
          for (int k = 0; k < 4; k++) {
            const uint64_t ad = sdesc(a0 + k * 32, 16, 1024);
            umma(d, ad, sdesc(b0 + k * 2048, 8192, 1024), ida, (uint32_t)(kb | k));
            if (Nb > 0) umma(d + 128, ad, sdesc(b0 + 16384 + k * 2048, 8192, 1024), idb, (uint32_t)(kb | k));
          }
          umma_commit(empty1 + s);
          if (kb == KB1 - 1) umma_commit(tf1 + buf);
        }
        __syncwarp();
      }
    }
  }
  {
    // GEMM1 epilogue on all 16 warps. Warps 4-15 take every tile (3 per TMEM quadrant); warps 0-3 join the CTA's last
    // tile (warps 0/1 after issuing), which then runs 4 warps per quadrant. Warp j of quadrant q takes the 16-column
    // chunks j, j+nwq, ...
    const int q = warp & 3, r = q * 32 + lane;
    const int ntc = (cta < p.T1) ? (p.T1 - cta + P - 1) / P : 0;
    uint32_t* stg = reinterpret_cast<uint32_t*>(ring + TC_B_STG) + warp * (TC_B_STGW / 4);
    float4* sqb = reinterpret_cast<float4*>(ring + TC_B_SQ);
    const bool whole = p.WHOLE != 0;
#if TC_STAMPS
    unsigned long long a_pre = 0, a_wait = 0, a_p1 = 0, a_img = 0, a_p2 = 0, a_imax = 0, a_red = 0;
#endif
    // the deferred W2 conversion is issued ahead of the tile loop at C=768 (inside the loop it spilled, r10)
    if constexpr (C_ >= 768) {
      if (ntc > 0 && warp >= 4) tc_w2_work<C_>(p, Ez * 16 + cta * 12 + (warp - 4), Wt, lane);
    }
    const int nch = (N1 + 15) >> 4;
    int ti = 0;
    for (int t = cta; t < p.T1; t += P, ti++) {
      const bool last = (ti == ntc - 1);
      if (!last && warp < 4) continue;
#if TC_STAMPS
      const unsigned long long q0 = gtime();
#endif
      const int nwq = last ? 4 : 3, j = last ? (warp >> 2) : (warp >> 2) - 1;
      const int bid = last ? 1 : 2, bn = nwq * 128, ep = last ? tid : tid - 128, w0 = last ? 0 : 4;
      const int m0 = (t % HT) * 128, t0 = (t / HT) * R;
      const int vcols = min(R, p.Mcols - t0);
      const int img0 = t0 / HWS, nimg = (t0 + vcols - 1) / HWS - img0 + 1;
      const int k = m0 + r;
      const float uk = __ldcg(p.uk + k), vk = __ldcg(p.vk + k), gwk = __ldg(p.gw + k);
      // per-token LN statistics (mu, rstd, -, valid) for the tile's N1 columns; warps 2-3 for the second of two tiles
      float4* ms = reinterpret_cast<float4*>(sm + ((ti & 1) ? TC_OFF_SQ : TC_OFF_MS));
      const bool early = last && ntc == 2;
      const int pw0 = early ? 2 : 4, pnw = early ? 2 : 8;
      if (warp >= pw0 && warp < pw0 + pnw) {
        for (int et = (warp - pw0) * 32 + lane; et < N1; et += pnw * 32) {
          const int gc = t0 + et, b = gc / HWS, hw = gc - b * HWS;
          float4 m = make_float4(0.f, 0.f, 0.f, 0.f);
          if (et < vcols && hw < HW_) {
            const float2* pp = reinterpret_cast<const float2*>(p.part) + (size_t)b * G * HW_ + hw;
            float2 v[G];
#pragma unroll
            for (int g = 0; g < G; g++) v[g] = __ldcg(pp + g * HW_);
            float s1 = 0.f, s2 = 0.f;
#pragma unroll
            for (int g = 0; g < G; g++) { s1 += v[g].x; s2 += v[g].y; }
            const float mu = s1 / (float)C_;
            const float var = fmaxf(s2 / (float)C_ - mu * mu, 0.f);
            m = make_float4(mu, rsqrtf(var + p.ln_eps), 0.f, 1.f);
          }
          ms[et] = m;
        }
      }
      if (C_ < 768 && ti == 0 && warp >= 4) tc_w2_work<C_>(p, Ez * 16 + cta * 12 + (warp - 4), Wt, lane);
      nbar(bid, bn);
#if TC_STAMPS
      const unsigned long long q1 = gtime();
#endif
      const uint32_t buf = ti & 1;
      mb_wait(tf1 + buf, (ti >> 1) & 1);
      tfa();
#if TC_STAMPS
      const unsigned long long q2 = gtime();
#endif
      const uint32_t taddr = tbase + ((uint32_t)(q * 32) << 16) + buf * 256;
      __half* hbase = p.hid + (size_t)(m0 + q * 32) * p.Mcols + t0;
      // pass 1: LN fold + GELU in fp32, sumsq per (image slot, k) per 8-column group, fp32 h back into TMEM
      float sq[TC_MAXI];
#pragma unroll
      for (int s = 0; s < TC_MAXI; s++) sq[s] = 0.f;
#pragma unroll 1
      for (int ch = j; ch < nch; ch += nwq) {
        uint32_t v[16];
        tld16(taddr + ch * 16, v);
        float s8a = 0.f, s8b = 0.f;
#pragma unroll
        for (int e = 0; e < 16; e++) {
          const float4 m = ms[ch * 16 + e];
          const float h = gelu_as(fmaf(m.y, fmaf(-m.x, uk, __uint_as_float(v[e])), vk)) * m.w;
          v[e] = __float_as_uint(h);
          if (e < 8) s8a = fmaf(h, h, s8a); else s8b = fmaf(h, h, s8b);
        }
        tst16(taddr + ch * 16, v);
        const int ia = (t0 + ch * 16) / HWS - img0, ib = (t0 + ch * 16 + 8) / HWS - img0;
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++) sq[s] += (ia == s ? s8a : 0.f) + (ib == s ? s8b : 0.f);
      }
      tst_wait();
      sqb[j * 128 + r] = make_float4(sq[0], sq[1], sq[2], sq[3]);
      nbar(bid, bn);
      float4 sl = make_float4(0.f, 0.f, 0.f, 0.f);
#pragma unroll
      for (int jj = 0; jj < 4; jj++)
        if (jj < nwq) { const float4 w_ = sqb[jj * 128 + r]; sl.x += w_.x; sl.y += w_.y; sl.z += w_.z; sl.w += w_.w; }
      if (j == 0) {
        if (whole) {
          // whole-image ranges: the tile holds the complete sumsq of its (image, k) cells, so gf is local
          const float g4[4] = {sqrtf(sl.x), sqrtf(sl.y), sqrtf(sl.z), sqrtf(sl.w)};
#pragma unroll
          for (int s = 0; s < TC_MAXI; s++) if (s < nimg) { const float w_ = warp_sum(g4[s]); if (lane == 0) atomicAdd(p.gsum + img0 + s, w_); }
        } else {
          float* gk = p.gsq + (size_t)img0 * C4 + k;
          atomicAdd(gk, sl.x);
          if (nimg > 1) atomicAdd(gk + C4, sl.y);
          if (nimg > 2) atomicAdd(gk + 2 * C4, sl.z);
          if (nimg > 3) atomicAdd(gk + 3 * C4, sl.w);
        }
      }
      nbar(bid, bn);
#if TC_STAMPS
      const unsigned long long q3 = gtime();
#endif
      if (warp == 4 && lane == 0) {
        // publish with red.release.gpu on one cell per range (whole: the cell of its first image, target HT) or on every
        // touched image (straddling, target HT x ranges touching the image); poll all cells in one ld.acquire loop;
        // departures issued back to back, the last departer resets the cell. (A fence.acq_rel.gpu + red.relaxed publish
        // cost 8-15 us at 14x14 in the r13 probes; per-image serial spins and departures cost ~1 us per extra image.)
        const int nc = whole ? 1 : nimg;
        unsigned int tg[TC_MAXI];
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++) {
          const int b = img0 + s;
          tg[s] = whole ? (unsigned int)HT : (unsigned int)(HT * (((b + 1) * HWS - 1) / R - (b * HWS) / R + 1));
        }
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++)
          if (s < nc) asm volatile("red.release.gpu.global.add.u32 [%0], 1;" ::"l"(g_img_cnt + (img0 + s) * 32) : "memory");
        bool done;
        do {
          done = true;
#pragma unroll
          for (int s = 0; s < TC_MAXI; s++)
            if (s < nc) {
              unsigned int cur;
              asm volatile("ld.acquire.gpu.global.u32 %0, [%1];" : "=r"(cur) : "l"(g_img_cnt + (img0 + s) * 32) : "memory");
              done = done && (cur >= tg[s]);
            }
        } while (!done);
        unsigned int old[TC_MAXI];
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++) {
          old[s] = 0u;
          if (s < nc) asm volatile("atom.relaxed.gpu.global.add.u32 %0, [%1], 1;" : "=r"(old[s]) : "l"(g_img_dep + (img0 + s) * 32) : "memory");
        }
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++)
          if (s < nc && old[s] == tg[s] - 1u) {
            asm volatile("st.relaxed.gpu.global.u32 [%0], 0;" ::"l"(g_img_cnt + (img0 + s) * 32) : "memory");
            asm volatile("st.relaxed.gpu.global.u32 [%0], 0;" ::"l"(g_img_dep + (img0 + s) * 32) : "memory");
          }
      }
      nbar(bid, bn);
#if TC_STAMPS
      const unsigned long long q4 = gtime();
#endif
      float sc[TC_MAXI];
      if (whole) {
        const float sl4[4] = {sl.x, sl.y, sl.z, sl.w};
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++)
          sc[s] = (s < nimg) ? fmaf(gwk * sqrtf(sl4[s]), 1.f / (__ldcg(p.gsum + img0 + s) / (float)C4 + p.eps), 1.f) : 1.f;
      } else {
        // gf of this row and inv_b per touched image: CTA reduction of sqrt(gsq[b][:]) over the participating threads,
        // all loads in one round (predicated float4 loads, touched images only)
        constexpr int NL4 = (C4 / 4 + 383) / 384;
        float gfo[TC_MAXI], psum[TC_MAXI];
        float4 gv[TC_MAXI][NL4];
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++) {
          const float* gs = p.gsq + (size_t)(img0 + s) * C4;
          gfo[s] = (s < nimg) ? __ldcg(gs + k) : 0.f;
#pragma unroll
          for (int i = 0; i < NL4; i++) {
            const int q4i = ep + bn * i;
            gv[s][i] = (s < nimg && q4i < C4 / 4) ? __ldcg(reinterpret_cast<const float4*>(gs) + q4i) : make_float4(0.f, 0.f, 0.f, 0.f);
          }
        }
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++) {
          float a = 0.f;
#pragma unroll
          for (int i = 0; i < NL4; i++) a += (sqrtf(gv[s][i].x) + sqrtf(gv[s][i].y)) + (sqrtf(gv[s][i].z) + sqrtf(gv[s][i].w));
          psum[s] = a;
          gfo[s] = sqrtf(gfo[s]);
        }
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++) if (s < nimg) { const float v = warp_sum(psum[s]); if (lane == 0) inv_s[warp * 4 + s] = v; }
        nbar(bid, bn);
#pragma unroll
        for (int s = 0; s < TC_MAXI; s++) {
          float tot = 0.f;
          if (s < nimg)
            for (int w = w0; w < 16; w++) tot += inv_s[w * 4 + s];
          sc[s] = (s < nimg) ? fmaf(gwk * gfo[s], 1.f / (tot / (float)C4 + p.eps), 1.f) : 1.f;
        }
      }
#if TC_STAMPS
      const unsigned long long q4b = gtime();
#endif
      // pass 2: h from TMEM, h' = fp16(h * s_img), staged coalesced stores
#pragma unroll 1
      for (int ch = j; ch < nch; ch += nwq) {
        uint32_t v[16];
        tld16(taddr + ch * 16, v);
        const int ia = (t0 + ch * 16) / HWS - img0, ib = (t0 + ch * 16 + 8) / HWS - img0;
        float fa = sc[0], fb = sc[0];
#pragma unroll
        for (int s = 1; s < TC_MAXI; s++) { if (ia == s) fa = sc[s]; if (ib == s) fb = sc[s]; }
        uint32_t w[8];
#pragma unroll
        for (int x = 0; x < 4; x++) {
          w[x] = h2u(__floats2half2_rn(__uint_as_float(v[2 * x]) * fa, __uint_as_float(v[2 * x + 1]) * fa));
          w[4 + x] = h2u(__floats2half2_rn(__uint_as_float(v[8 + 2 * x]) * fb, __uint_as_float(v[9 + 2 * x]) * fb));
        }
        tc_stage16(stg, w, hbase, p.Mcols, ch, vcols, lane);
      }
      tfb();
      nbar(bid, bn);
      if (warp == 4 && lane == 0) mb_arrive1(te1 + buf);
#if TC_STAMPS
      if (warp == 4) {
        const unsigned long long q5 = gtime();
        a_pre += q1 - q0; a_wait += q2 - q1; a_p1 += q3 - q2; a_img += q4 - q3; a_red += q4b - q4; a_p2 += q5 - q4;
        if (q4 - q3 > a_imax) a_imax = q4 - q3;
      }
#endif
    }
#if TC_STAMPS
    if (warp == 4 && lane == 0) {
      STAMP(4); p.st[cta * 24 + 11] = a_pre; p.st[cta * 24 + 12] = a_wait; p.st[cta * 24 + 19] = a_p1;
      p.st[cta * 24 + 18] = a_img; p.st[cta * 24 + 20] = a_p2; p.st[cta * 24 + 21] = a_imax; p.st[cta * 24 + 22] = ntc;
